INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (10, 0, 0, 11, 1, 107911, "こんなに人がいっぱいいる商機、\n見逃すわけにはいかないにゃ！", 1, 0, 944, 19440038);
