INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (7, 0, 0, 11, 1, 126811, "それ、アキノさんの許可とってるの？\nもし無許可だったら怒られるわよ？", 1, 0, 944, 19440043);
