INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (8, 0, 0, 11, 1, 107911, "大丈夫にゃ。バレないように…\nってやばいにゃ！　見回りだにゃ！", 0.5, 0, 944, 19440046);
