INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (0, 0.1, 1, 3, "45_yui_shy_loop", 122611, "45_yui_shy_in", "", 0.1, 945, 19450030);
INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (0, 0.1, 1, 3, "45_yui_shy_loop", 1, "45_yui_shy_in", "", 0.1, 945, 19450031);
INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES ("", "", "", 21, 0, "vo_fpc", "vo_fpc_30504", "", "", 945, 19450032);
INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (5, 0, 0, 11, 1, 122611, "…うん、やっちゃった…\nおっきなハートマーク…\nやっぱりこれは無しで！\nマコトちゃん食べてくれる！？", 1, 0, 945, 19450033);
INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES ("", "", "", 91, "", 0, "", "", "", 945, 19450034);
INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES (1, "", "", 3, "", 110411, "45_makoto_idle", "", 0.1, 945, 19450035);
INSERT INTO `v1_74b805e396769085a154cc715bfb6bf4efa721aeff718d76e747674fb43630eb` VALUES ("", "", "", 21, 0, "vo_fpc", "vo_fpc_30505", "", "", 945, 19450036);
